 if(n.id==='15:822')return `<input class="layer native-input" style="${inputCss(style)}" id="visitOrder" aria-label="Your order" placeholder="What did you have?" value="${esc(logDraft.order)}">`;
 if(n.id==='15:852')return `<textarea class="layer native-input" style="${css(style)}" id="visitComment" aria-label="Comment" placeholder="Taste, atmosphere, company, or anything worth remembering...">${esc(logDraft.comment)}</textarea>`;
 return `<${tag} class="layer ${n.type==='TEXT'?'layer-text':''}" data-node="${n.id}"${attrs} style="${css(style)}">${content}</${tag}>`;
