function modal(title,body,variant=''){const el=document.createElement('dialog');el.className=`modal ${variant}`.trim();const heading=variant==='figma-form-modal'?`<div class="figma-form-heading"><div class="figma-form-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="3.2"></circle><path d="M3.5 19c.5-3.2 2.4-5 5.5-5s5 1.8 5.5 5M17 8v6m-3-3h6"></path></svg></div><h2>${title}</h2></div>`:`<h2>${title}</h2>`;el.innerHTML=`<button type="button" class="close-modal" aria-label="Close">×</button>${heading}${body}`;document.body.append(el);el.querySelector('.close-modal').onclick=()=>el.close();el.addEventListener('close',()=>el.remove());el.showModal();return el;}
function normalizeUsername(value){return String(value||'').trim().replace(/^@+/,'');}
function formatUsernameField(value){const username=normalizeUsername(value);return username?`@${username}`:'';}
function validUsername(value){return /^[a-zA-Z0-9_]{3,20}$/.test(value);}
async function saveUsername(value,status,modalElement){const username=normalizeUsername(value);if(!validUsername(username)){status.textContent='Use 3–20 letters, numbers, or underscores.';return false;}status.textContent='Saving…';const result=await account.client.from('brewlog_profiles').upsert({user_id:account.user.id,username},{onConflict:'user_id'});if(result.error){status.textContent=result.error.code==='23505'?'That username is already taken.':'Could not save that username.';return false;}account.username=username;account.profileError='';if(modalElement)modalElement.close();render();toast('Username updated.');return true;}
