function setCafeRating(name,value){if(value)saved.ratings[name]=value;else delete saved.ratings[name];persist();document.querySelectorAll('[data-cafe]').forEach(card=>{if(card.dataset.cafe!==name)return;card.querySelectorAll('[data-action="rate"]').forEach(star=>{const filled=Number(star.dataset.rating)<=value;star.setAttribute('aria-pressed',String(filled));star.querySelectorAll('svg path').forEach(path=>{path.setAttribute('fill',filled?'#f04e23':'transparent');path.setAttribute('stroke',filled?'#f04e23':'#b6b4a9');});});const ratingValue=card.querySelector('[data-rating-value]');if(ratingValue)ratingValue.textContent=value?Number(value).toFixed(1):'—';});}
document.addEventListener('dblclick',event=>{const visitStar=event.target.closest('[data-action="visit-rate"]');if(visitStar&&route==='log'){event.preventDefault();updateVisitRating(0);toast('Visit rating cleared.');return;}const star=event.target.closest('[data-action="rate"]');if(!star)return;const name=star.closest('[data-cafe]')?.dataset.cafe;if(name){event.preventDefault();setCafeRating(name,0);toast('Cafe rating removed.');}});
document.addEventListener('input',event=>{if(route==='log'&&event.target.matches('#visitCafe,#visitLocation,#visitOrder,#visitComment'))captureLogDraft();validateVisit();});
document.addEventListener('change',event=>{if(route==='log'&&event.target.matches('#visitDate'))captureLogDraft();});
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),4000);}
const pullRefresh=document.querySelector('#pull-refresh');let pullStartY=0,pullDistance=0,pulling=false;
document.addEventListener('touchstart',event=>{if(innerWidth>402||scrollY>0||event.touches.length!==1||event.target.closest('input,textarea,select,dialog'))return;pullStartY=event.touches[0].clientY;pullDistance=0;pulling=true;},{passive:true});
document.addEventListener('touchmove',event=>{if(!pulling||innerWidth>402)return;pullDistance=Math.max(0,event.touches[0].clientY-pullStartY);if(!pullDistance)return;const distance=Math.min(pullDistance*.45,88);if(pullRefresh){pullRefresh.style.transform=`translate(-50%,${distance-44}px)`;pullRefresh.classList.toggle('visible',distance>8);pullRefresh.classList.toggle('ready',distance>=64);pullRefresh.textContent=distance>=64?'Release to refresh':'Pull to refresh';}if(distance>8&&scrollY<=0)event.preventDefault();},{passive:false});
document.addEventListener('touchend',()=>{if(!pulling)return;const shouldRefresh=pullDistance*.45>=64;pulling=false;if(shouldRefresh){if(pullRefresh){pullRefresh.textContent='Refreshing…';pullRefresh.classList.add('visible');}location.reload();}else if(pullRefresh){pullRefresh.classList.remove('visible','ready');pullRefresh.style.transform='';}},{passive:true});
document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>go(b.dataset.route));window.addEventListener('hashchange',()=>{if(route==='log')captureLogDraft();route=location.hash.slice(1)||'journal';render();});window.addEventListener('resize',resize);render();
fetch('/api/cafes').then(r=>{if(!r.ok)throw Error('Directory unavailable');return r.json();}).then(data=>{directory=uniqueCafes(data.cafes||[]);if(route==='cafes')render();else if(route==='log'){const names=[...directory,...examples].map(c=>nameOf(c)).filter((name,index,list)=>name&&list.indexOf(name)===index),list=document.querySelector('#cafe-options');if(list)list.innerHTML=names.map(name=>`<option value="${esc(name)}"></option>`).join('');}}).catch(()=>console.info('Showing the Figma preview directory.'));
